#!/usr/bin/env node
/**
 * Bundles the browser-side MCP App (browser/taskTimelineApp.ts — the
 * ext-apps host bridge plus the timeline renderer) into a single minified
 * IIFE, and writes it as a generated TS module exporting that JS as a
 * string. The Node-side src/ui/taskTimeline.ts imports the string and
 * inlines it into the `ui://` resource's HTML — the Node build (tsup)
 * never touches esbuild's browser output directly, it just sees a string
 * constant.
 *
 * Runs as a `pre*` hook before build/dev/typecheck/test (see package.json)
 * so the generated file always exists before anything that imports it.
 * Mirrors scripts/build-ifc-viewer.mjs.
 */
import { build } from 'esbuild';
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));

const result = await build({
  entryPoints: [path.join(root, 'browser', 'taskTimelineApp.ts')],
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: 'es2020',
  write: false,
  minify: true,
  legalComments: 'none',
});

if (result.outputFiles.length !== 1) {
  throw new Error(`Expected exactly one esbuild output file, got ${result.outputFiles.length}`);
}

const script = result.outputFiles[0].text;
const outPath = path.join(root, 'src', 'ui', 'taskTimelineBundle.generated.ts');
const header = [
  '// GENERATED by scripts/build-task-timeline.mjs — do not edit by hand.',
  '// Bundles browser/taskTimelineApp.ts (the MCP App running inside the',
  '// ui://dalux-build/task-timeline iframe) into a single inline <script>.',
  '// Regenerate with `npm run build:app`.',
  '',
].join('\n');

writeFileSync(outPath, `${header}export const TASK_TIMELINE_BUNDLE_JS = ${JSON.stringify(script)};\n`);
console.log(`Wrote ${path.relative(root, outPath)} (${script.length} bytes)`);
